local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local SmallPackageDownloaded = "SmallPackageDownloaded"
local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
local AppEngine = CS.Engine.Lib.AppEngine

---@class MaidCoffeeSceneTvNode
local MaidCoffeeSceneTvNode = Class('MaidCoffeeSceneTvNode')
function MaidCoffeeSceneTvNode:__init()
    
end

function MaidCoffeeSceneTvNode:__delete()
    
end

local function IsSmallPackage()
    local isSmallPackage = checkNumber(AppEngine.GetConfig("Engine", "IsSmallPackage", false))
    local preVersion = PlayerPrefsUtility.GetEncryptedString(SmallPackageDownloaded, "")
    local isSmall = false
    if isSmallPackage == 1 and preVersion ~= CS.UnityEngine.Application.version then
        ---最新的分包的逻辑，要进行检测更新相关的逻辑
        isSmall = true
    end
    return isSmall
end

function MaidCoffeeSceneTvNode:Awake()
    if  not IsSmallPackage() then
        self.tvNodeStatusEvent = Bind(self,self.OnTvNodeStatusChange)
        Events.AddListener("MaidCoffeeTvNodeChangeState",self.tvNodeStatusEvent)
        self:InitNodeEnv()
    end
end

function MaidCoffeeSceneTvNode:InitNodeEnv()
    if self.MenuRoot then
        local env = CfUtils.GetLuaScr(self.MenuRoot,"Game.MaidCoffee.MaidCoffeeUIDialog.OverseaManageMenuSettingNode")
        self.menuRootEnv = env
    end
end

function MaidCoffeeSceneTvNode:RefreshShowInfo()
    if not isNull(self.menuRootEnv) then
        self.menuRootEnv:RefreshShowInfo()
        self.menuRootEnv:RefreshRedPoint()
    end
end

function MaidCoffeeSceneTvNode:RefreshManagerShow()
    if not isNull(self.menuRootEnv) then
        self.menuRootEnv:RefreshManagerShow()
    end
end

function MaidCoffeeSceneTvNode:OnTvNodeStatusChange(status)
    self:SetTvNodeStatus(status)
end

function MaidCoffeeSceneTvNode:SetGoToStatus(status)
    if not isNull(self.menuRootEnv) then
        self.menuRootEnv:SetGoToStatus(status)
    end
end

function MaidCoffeeSceneTvNode:SetTvNodeStatus(status)
    KTool.SetActive(self.BgTv.gameObject,status)
    if not isNull(self.menuRootEnv) then
        self.menuRootEnv:SetMenuNoteStatus(status)
    end
end

function MaidCoffeeSceneTvNode:Start()
    local lastDialog = UIModule.CurrentScreen:LastDialog()
    if (lastDialog and lastDialog.Argument.id == Constants.UITypeIds.UIMaidCoffeeManagerDialog) or (UIModule.CurrentScreen and UIModule.CurrentScreen.Argument.id == Constants.UITypeIds.UIMaidCoffeeEnterScene) then
        self:RefreshShowInfo()
    end
end

function MaidCoffeeSceneTvNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    if self.tvNodeStatusEvent then
        Events.RemoveListener("MaidCoffeeTvNodeChangeState",self.tvNodeStatusEvent)
        self.tvNodeStatusEvent = nil
    end
end

return MaidCoffeeSceneTvNode